@warp k -> ruta_13 spawn=east
# The fishing guru: the first talk gives the CAÑA VIEJA (a full bag keeps flag 830 clear and he gives it at the next talk).
@script guru npc
    npc_face_hero guru
    jf cana_vieja_given said
    say ruta12.guru.a
    call guru_gift
    end
  said:
    say ruta12.guru.after
@end
@script guru_gift called
    say ruta12.guru.b
    give_item cana_junco 1
    jv 0 0 full
    item_var 0 cana_junco
    say gl.gift
    setf cana_vieja_given
    say ruta12.guru.about
    end
  full:
    say gl.found.full
@end
